create table if not exists public.vendor_payable_ledger_entries (id bigint generated always as identity primary key,vendor_id bigint not null references public.vendors(id),entry_type text not null check (entry_type in ('PURCHASE','PAYMENT','PURCHASE_RETURN','ADJUSTMENT')),reference_type text not null,reference_id bigint not null,debit numeric not null default 0 check (debit >= 0),credit numeric not null default 0 check (credit >= 0),entry_date date not null default current_date,description text,created_at timestamptz not null default now(),constraint vendor_payable_entry_side check (not (debit > 0 and credit > 0)),constraint vendor_payable_reference_unique unique (entry_type,reference_type,reference_id)); create index if not exists vendor_payable_vendor_date_idx on public.vendor_payable_ledger_entries(vendor_id,entry_date,id); create or replace view public.vendor_payable_balances as select v.id vendor_id,v.name vendor_name,coalesce(sum(l.credit),0)::numeric total_credits,coalesce(sum(l.debit),0)::numeric total_debits,(coalesce(sum(l.credit),0)-coalesce(sum(l.debit),0))::numeric outstanding_balance from public.vendors v left join public.vendor_payable_ledger_entries l on l.vendor_id=v.id group by v.id,v.name; insert into public.accounts(code,name,account_type,normal_balance,is_active) values ('1010','Bank','ASSET','DEBIT',true),('1090','Other Payment Account','ASSET','DEBIT',true),('1300','Input Tax Recoverable','ASSET','DEBIT',true) on conflict(code) do nothing; create or replace function public.record_purchase_with_payable(p_vendor_id bigint,p_warehouse_id bigint,p_items jsonb,p_purchase_date date default current_date,p_invoice_number text default null,p_discount numeric default 0,p_tax numeric default 0,p_notes text default null,p_idempotency_principal text default null,p_idempotency_operation text default 'purchase.create',p_idempotency_key text default null,p_request_fingerprint text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_purchase_result jsonb; v_purchase_id bigint; v_purchase_total numeric; v_purchase_subtotal numeric; v_purchase_tax numeric; v_purchase_date date; v_purchase_invoice text; v_journal_id bigint; begin v_purchase_result:=public.record_purchase(p_vendor_id,p_warehouse_id,p_items,p_purchase_date,p_invoice_number,p_discount,p_tax,p_notes,p_idempotency_principal,p_idempotency_operation,p_idempotency_key,p_request_fingerprint); v_purchase_id:=(v_purchase_result->'response_body'->'data'->'purchase'->>'id')::bigint; if v_purchase_id is null then raise exception 'Purchase transaction did not return a purchase id'; end if; select total,subtotal,tax,purchase_date,invoice_number into v_purchase_total,v_purchase_subtotal,v_purchase_tax,v_purchase_date,v_purchase_invoice from public.purchases where id=v_purchase_id; insert into public.vendor_payable_ledger_entries(vendor_id,entry_type,reference_type,reference_id,debit,credit,entry_date,description) values(p_vendor_id,'PURCHASE','PURCHASE',v_purchase_id,0,v_purchase_total,v_purchase_date,'Purchase payable') on conflict(entry_type,reference_type,reference_id) do nothing; insert into public.accounting_journal_entries(entry_date,source_type,source_id,description) values(v_purchase_date,'PURCHASE',v_purchase_id,'Purchase payable') on conflict(source_type,source_id) do nothing returning id into v_journal_id; if v_journal_id is not null then insert into public.accounting_journal_lines(journal_entry_id,account_code,debit,credit,description) values(v_journal_id,'1200',greatest(v_purchase_subtotal-coalesce(p_discount,0),0),0,'Inventory from purchase'),(v_journal_id,'1300',coalesce(v_purchase_tax,0),0,'Input tax from purchase'),(v_journal_id,'2000',0,v_purchase_total,'Vendor accounts payable'); end if; return v_purchase_result; end; $$; create or replace function public.record_vendor_payment_with_accounting(p_vendor_id bigint,p_amount numeric,p_payment_method text,p_allocations jsonb,p_payment_date date default current_date,p_reference text default null,p_notes text default null,p_principal_scope text default 'service_role',p_idempotency_key text default null,p_request_fingerprint text default null) returns bigint language plpgsql security definer set search_path=public as $$ declare v_payment_id bigint;v_journal_id bigint;v_account_code text;begin v_payment_id:=public.record_vendor_payment(p_vendor_id,p_amount,p_payment_method,p_allocations,p_payment_date,p_reference,p_notes,p_principal_scope,p_idempotency_key,p_request_fingerprint);insert into public.vendor_payable_ledger_entries(vendor_id,entry_type,reference_type,reference_id,debit,credit,entry_date,description) values(p_vendor_id,'PAYMENT','VENDOR_PAYMENT',v_payment_id,p_amount,0,coalesce(p_payment_date,current_date),'Vendor payment against payable') on conflict(entry_type,reference_type,reference_id) do nothing;v_account_code:=case p_payment_method when 'CASH' then '1000' when 'BANK' then '1010' else '1090' end;insert into public.accounting_journal_entries(entry_date,source_type,source_id,description) values(coalesce(p_payment_date,current_date),'VENDOR_PAYMENT',v_payment_id,'Vendor payment') on conflict(source_type,source_id) do nothing returning id into v_journal_id;if v_journal_id is not null then insert into public.accounting_journal_lines(journal_entry_id,account_code,debit,credit,description) values(v_journal_id,'2000',p_amount,0,'Reduce vendor accounts payable'),(v_journal_id,v_account_code,0,p_amount,'Vendor payment funding account');end if;return v_payment_id;end; $$; revoke all on function public.record_purchase_with_payable(bigint,bigint,jsonb,date,text,numeric,numeric,text,text,text,text,text) from public,anon,authenticated; grant execute on function public.record_purchase_with_payable(bigint,bigint,jsonb,date,text,numeric,numeric,text,text,text,text,text) to service_role; revoke all on function public.record_vendor_payment_with_accounting(bigint,numeric,text,jsonb,date,text,text,text,text,text) from public,anon,authenticated; grant execute on function public.record_vendor_payment_with_accounting(bigint,numeric,text,jsonb,date,text,text,text,text,text) to service_role;